/**
 * Tiny synthetic photos (24x16 gradients made for the tests, not real photographs).
 * The *_WITH_GPS files carry a camera make and a made-up GPS position in their EXIF,
 * so tests can prove location data never reaches a stored or served file.
 */
const bytes = (b64: string) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

export const JPEG_WITH_GPS = bytes(
  '',
);
export const WEBP_WITH_GPS = bytes(
  '',
);
export const PLAIN_JPEG = bytes(
  '',
);
